  EXPECT_EQ(parse_number("-0x1000000000000000000000000000000000000000000000000", nullptr), parse_number("-0x20000000000000001ffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0x1000000000000000000000000000000000000000000000000", nullptr), parse_number("-0x20000000000000001ffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr), parse_number("-0x20000000000000001ffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr), parse_number("-0x20000000000000001ffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000003ffffffffffffffff", nullptr), parse_number("-0x20000000000000001ffffffffffffffff", nullptr).logical_and(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000040000000000000000", nullptr), parse_number("-0x20000000000000001ffffffffffffffff", nullptr).logical_and(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
