  EXPECT_EQ(parse_number("0xfffffffffffffffe", nullptr), parse_number("0x10000000000000001fffffffffffffffe", nullptr).logical_and(parse_number("-0xffffffffffffffff00000000000000010000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffe", nullptr), parse_number("0x10000000000000001fffffffffffffffe", nullptr).logical_and(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0x10000000000000000", nullptr), parse_number("0x10000000000000001fffffffffffffffe", nullptr).logical_and(parse_number("-0xffffffffffffffff00000000000000010000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0x10000000000000000", nullptr), parse_number("0x10000000000000001fffffffffffffffe", nullptr).logical_and(parse_number("-0xffffffffffffffff0000000000000000ffffffffffffffff", nullptr)));
