  EXPECT_EQ(parse_number("0xffffffffffffffff", nullptr), parse_number("0xfffffffffffffffefffffffffffffffeffffffffffffffff", nullptr).logical_and(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0x0", nullptr), parse_number("0xfffffffffffffffefffffffffffffffeffffffffffffffff", nullptr).logical_and(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000000", nullptr)));
