  EXPECT_EQ(parse_number("0x2", nullptr), parse_number("0xfffffffffffffffefffffffffffffffeffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
