  EXPECT_EQ(parse_number("0x2", nullptr), parse_number("0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffe", nullptr), parse_number("0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr).logical_and(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
