  EXPECT_EQ(parse_number("0x0", nullptr), parse_number("0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_and(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
